	// @vue/component
	const MenuButton = {
		name: 'ui-top-panel-menu-button',
		components: {
			UiButton: ui_vue3_components_button.Button,
			BMenu: ui_vue3_components_menu.BMenu
		},
		props: {
			text: {
				type: String,
				default: null
			},
			icon: {
				type: String,
				default: null
			},
			buttonStyle: {
				type: String,
				default: null
			},
			/** @type MenuOptions */
			options: {
				type: {},
				default: () => ({})
			},
			/** The accessible name of an icon-only button, which has no text to be named by. */
			ariaLabel: {
				type: String,
				default: null
			}
		},
		data() {
			return {
				isMenuShown: false
			};
		},
		computed: {
			menuOptions() {
				return {
					bindElement: this.$refs.button.button.button,
					autoHide: true,
					offsetLeft: this.$refs.button.button.button.offsetWidth / 2 - 120,
					width: 240,
					...this.options
				};
			},
			buttonAttributes() {
				return {
					'aria-haspopup': 'menu',
					'aria-expanded': this.isMenuShown ? 'true' : 'false',
					'aria-label': this.ariaLabel
				};
			}
		},
		watch: {
			buttonAttributes() {
				this.syncButtonAttributes();
			}
		},
		mounted() {
			this.syncButtonAttributes();
		},
		methods: {
			/**
			 * UiButton builds its native button imperatively, so attributes bound in the template never
			 * reach it and have to be written to the button element on every change.
			 */
			syncButtonAttributes() {
				this.$refs.button?.button?.setProps(this.buttonAttributes);
			}
		},
		template: `
		<UiButton
			:text="text"
			:leftIcon="icon"
			:style="buttonStyle"
			ref="button"
			@click="isMenuShown = true"
		/>
		<BMenu
			v-if="isMenuShown"
			:options="menuOptions"
			@close="isMenuShown = false"
		/>
	`
	};

	// @vue/component
	const SplitButton = {
		name: 'split-button',
		props: {
			id: {
				type: String,
				default: ''
			},
			text: {
				type: String,
				default: ''
			},
			icon: {
				type: String,
				default: null
			},
			style: {
				type: String,
				default: null
			},
			loading: Boolean,
			disabled: Boolean,
			describedBy: {
				type: String,
				default: null
			}
		},
		emits: ['click', 'mainClick', 'menuClick'],
		data() {
			return {
				isMounted: false
			};
		},
		watch: {
			icon(icon) {
				const classes = this.button.getContainer().classList;
				classes.forEach(className => {
					if (className.startsWith('ui-btn-icon-')) {
						main_core.Dom.removeClass(this.button.getContainer(), className);
					}
				});
				if (icon && !icon.startsWith('ui-btn-icon')) {
					main_core.Dom.addClass(this.button.getContainer(), '--with-icon');
					return;
				}
				this.button.setProperty('icon', icon, ui_vue3_components_button.ButtonIcon);
				main_core.Dom.removeClass(this.button.getContainer(), '--with-icon');
				main_core.Dom.toggleClass(this.button.getContainer(), ['ui-icon-set__scope', icon], Boolean(icon));
			},
			loading: {
				handler(loading) {
					if (loading !== this.button?.isWaiting()) {
						this.button?.setWaiting(loading);
					}
				},
				immediate: true
			},
			style(style) {
				this.button.setStyle(style);
			},
			disabled(disabled) {
				this.button?.setDisabled(disabled);
			},
			describedBy() {
				this.applyDescribedBy();
			}
		},
		methods: {
			applyDescribedBy() {
				const container = this.button?.getMainButton()?.getContainer();
				if (!container) {
					return;
				}
				if (this.describedBy) {
					container.setAttribute('aria-describedby', this.describedBy);
				} else {
					container.removeAttribute('aria-describedby');
				}
			}
		},
		created() {
			const button = new ui_buttons.SplitButton({
				id: this.id,
				text: this.text,
				useAirDesign: true,
				style: this.style,
				onclick: () => {
					this.$emit('click');
				},
				mainButton: {
					dataset: {
						testid: 'bizprocdesigner-split-button-main'
					},
					onclick: () => {
						this.$emit('mainClick');
					}
				},
				menuButton: {
					dataset: {
						testid: 'bizprocdesigner-split-button-menu'
					},
					onclick: () => {
						this.$emit('menuClick');
					}
				}
			});
			button.setDisabled(this.disabled);
			if (this.icon) {
				button.addClass(`${this.icon} ui-icon-set__scope --with-left-icon`);
			}
			this.button = button;
		},
		mounted() {
			const button = this.button?.render();
			this.$refs.button.after(button);
			this.applyDescribedBy();
			this.isMounted = true;
		},
		unmounted() {
			this.button?.getContainer()?.remove();
		},
		template: `
		<button v-if="!isMounted" ref="button"></button>
	`
	};

