	class FileService extends main_core_events.EventEmitter {
		#adapter = null;
		constructor(id) {
			super();
			this.setEventNamespace('Bizporcdesigner.TextEditor.Files');
			this.#initAdapter(id);
		}
		static get EVENT_NAMES() {
			return {
				ON_FILE_ADD: 'onFileAdd',
				ON_FILE_COMPLETE: 'onFileComplete',
				ON_FILE_REMOVE: 'onFileRemove'
			};
		}
		#initAdapter(id) {
			this.#adapter = new ui_uploader_vue.VueUploaderAdapter({
				id,
				controller: 'disk.uf.integration.diskUploaderController',
				imagePreviewHeight: 1200,
				imagePreviewWidth: 1200,
				imagePreviewQuality: 0.85,
				ignoreUnknownImageTypes: true,
				treatOversizeImageAsFile: true,
				multiple: true,
				maxFileSize: null
			});
			this.#adapter.subscribeFromOptions({
				'Item:onAdd': event => {
					const {
						item: file
					} = event.getData();
					this.emit(FileService.EVENT_NAMES.ON_FILE_ADD, file);
				},
				'Item:onComplete': event => {
					const {
						item: file
					} = event.getData();
					this.emit(FileService.EVENT_NAMES.ON_FILE_COMPLETE, file);
				},
				'Item:onRemove': event => {
					const {
						item: file
					} = event.getData();
					this.emit(FileService.EVENT_NAMES.ON_FILE_REMOVE, {
						file
					});
				}
			});
		}
		browse(params) {
			main_core.Runtime.loadExtension('disk.uploader.user-field-widget').then(({
				UserFieldMenu
			}) => {
				const menu = new UserFieldMenu({
					dialogId: 'bizprocdesigner-text-editor',
					uploader: this.#adapter.getUploader(),
					compact: params.compact || false,
					menuOptions: {
						minWidth: 220,
						animation: 'fading',
						closeByEsc: true,
						bindOptions: {
							forceBindPosition: true
						},
						events: {
							onPopupClose: () => {
								params.onHideCallback?.();
							},
							onPopupShow: () => {
								params.onShowCallback?.();
							}
						}
					}
				});
				menu.show(params.bindElement);
			}).catch(error => console.error(error));
		}
		getAdapter() {
			return this.#adapter;
		}
		getFileItems() {
			return this.#adapter.getItems();
		}
		loadInitialFiles(files) {
			if (!main_core.Type.isArrayFilled(files)) {
				return;
			}
			const uploader = this.#adapter.getUploader();
			if (uploader.getFiles().length > 0) {
				return;
			}
			uploader.addFiles(files);
		}
		destroy() {
			this.#adapter.unsubscribeAll('Item:onAdd');
			this.#adapter.unsubscribeAll('Item:onComplete');
			this.#adapter.unsubscribeAll('Item:onRemove');
			this.#adapter.getUploader().destroy();
		}
	}
	const fileServicesMap = {};
	const fileServices = {
		get(blockId) {
			fileServicesMap[blockId] ??= new FileService(blockId);
			return fileServicesMap[blockId];
		},
		delete(blockId) {
			fileServicesMap[blockId]?.destroy();
			delete fileServicesMap[blockId];
		}
	};

	class TextEditorService extends main_core_events.EventEmitter {
		#id;
		#editor = null;
		#isEdit = ui_vue3.ref(false);
		#isShowSaveConfirm = ui_vue3.ref(false);
		#saveConfirmResolvers = null;
		#isPendingSaveConfirm = true;
		#fileService = null;
		#uploaderAdapter;
		constructor(id) {
			super();
			this.setEventNamespace('Bizprocdesigner.TextEditor');
			this.#id = id;
			this.initFileService(id);
			this.#initEditor();
			this.#subscribeToEvents();
		}
		static get EVENT_NAMES() {
			return {
				ON_SAVE: 'onSave',
				ON_ABORT: 'onAbort',
				ON_EDIT: 'onEdit',
				ON_CHANGE_EDITOR: 'onChangeEditor',
				ON_BLUR_EDITOR: 'onBlurEditor'
			};
		}
		get isEdit() {
			return this.#isEdit;
		}
		get isShowSaveConfirm() {
			return this.#isShowSaveConfirm;
		}
		initFileService(id) {
			this.#fileService = fileServices.get(id);
			this.#uploaderAdapter = this.#fileService.getAdapter();
		}
		#subscribeToEvents() {
			this.#fileService.subscribe(FileService.EVENT_NAMES.ON_FILE_COMPLETE, event => this.onFileComplete(event));
			this.#fileService.subscribe(FileService.EVENT_NAMES.ON_FILE_REMOVE, event => this.onFileRemove(event));
		}
		#unsubscribeToEvents() {
			this.#fileService.unsubscribeAll(FileService.EVENT_NAMES.ON_FILE_COMPLETE);
			this.#fileService.unsubscribeAll(FileService.EVENT_NAMES.ON_FILE_REMOVE);
		}
		#initEditor() {
			this.#editor = new ui_textEditor.TextEditor({
				...ui_textEditor.BasicEditor.getDefaultOptions(),
				visualOptions: {
					borderRadius: '0px',
					borderWidth: 0
				},
				newLineMode: 'paragraph',
				file: {
					mode: 'disk',
					files: this.getFiles()
				},
				events: {
					onChange: () => this.#handleEditorChange(),
					onBlur: () => this.#handleEditorBlur()
				},
				plugins: [...new Set([...ui_textEditor.BasicEditor.getDefaultOptions().plugins, 'Quote', 'Code', 'Image'])],
				removePlugins: [],
				toolbar: ['bold', 'italic', 'underline', 'strikethrough', '|', 'numbered-list', 'bulleted-list', '|', 'link', '|', 'quote', 'code', 'image']
			});
		}
		#handleEditorChange() {
			this.emit(TextEditorService.EVENT_NAMES.ON_CHANGE_EDITOR, this.#editor.getText());
		}
		#handleEditorBlur() {
			this.emit(TextEditorService.EVENT_NAMES.ON_BLUR_EDITOR);
		}
		getEditor() {
			return this.#editor;
		}
		setText(text) {
			this.#editor.setText(text);
		}
		onFocus() {
			this.#editor.focus(null, {
				defaultSelection: 'rootEnd'
			});
		}
		onEdit(text) {
			setTimeout(() => this.onFocus(), 100);
			if (main_core.Type.isString(text)) {
				this.setText(text);
			}
			this.#isEdit.value = true;
			this.emit(TextEditorService.EVENT_NAMES.ON_EDIT);
		}
		onSave() {
			this.#isEdit.value = false;
			this.emit(TextEditorService.EVENT_NAMES.ON_SAVE, this.#editor.getText());
		}
		onAbort() {
			this.#isEdit.value = false;
			this.emit(TextEditorService.EVENT_NAMES.ON_ABORT);
		}
		insertFile(fileInfo) {
			this.#editor.dispatchCommand(ui_textEditor.Plugins.File.INSERT_FILE_COMMAND, {
				serverFileId: fileInfo.serverFileId,
				width: 600,
				height: 600,
				info: ui_vue3.toRaw(fileInfo)
			});
		}
		getFiles() {
			return this.#uploaderAdapter.getItems();
		}
		onFileComplete(event) {
			const file = event.getData();
			this.#editor.dispatchCommand(ui_textEditor.Plugins.File.ADD_FILE_COMMAND, file);
		}
		onFileRemove(event) {
			const {
				file
			} = event.getData();
			this.#editor.dispatchCommand(ui_textEditor.Plugins.File.REMOVE_FILE_COMMAND, {
				serverFileId: file.serverFileId,
				skipHistoryStack: true
			});
		}
		#createSaveConfirmResolvers() {
			this.#isPendingSaveConfirm = true;
			let resolve = null;
			let reject = null;
			let promise = new Promise((res, rej) => {
				resolve = res;
				reject = rej;
			});
			this.#saveConfirmResolvers = {
				promise,
				resolve,
				reject
			};
			this.#saveConfirmResolvers.promise.finally(() => {
				this.#isPendingSaveConfirm = false;
			});
		}
		onShowConfirmSave() {
			this.#createSaveConfirmResolvers();
			this.#isShowSaveConfirm.value = true;
			return this.#saveConfirmResolvers.promise;
		}
		onHideConfirmSave() {
			this.#isShowSaveConfirm.value = false;
		}
		onCloseConfirm() {
			if (this.#isPendingSaveConfirm) {
				this.#saveConfirmResolvers.reject();
			}
			this.#isShowSaveConfirm.value = false;
			this.#saveConfirmResolvers = null;
		}
		onSaveConfirm() {
			this.onSave();
			this.#saveConfirmResolvers.resolve();
		}
		onAbortConfirm() {
			this.onAbort();
			this.#saveConfirmResolvers.resolve();
		}
		destroy() {
			this.#unsubscribeToEvents();
			this.unsubscribeAll(TextEditorService.EVENT_NAMES.ON_SAVE);
			this.unsubscribeAll(TextEditorService.EVENT_NAMES.ON_ABORT);
			this.unsubscribeAll(TextEditorService.EVENT_NAMES.ON_EDIT);
			this.unsubscribeAll(TextEditorService.EVENT_NAMES.ON_CHANGE_EDITOR);
			this.unsubscribeAll(TextEditorService.EVENT_NAMES.ON_BLUR_EDITOR);
			this.#editor?.destroy();
		}
	}
