	// @vue/component
	const SaveConfirmDialog = {
		name: 'SaveConfirmDialog',
		emits: ['save', 'abort', 'close'],
		mounted() {
			this.getDialog().setContent(this.$refs.content);
			this.getDialog().show();
		},
		unmounted() {
			this.instance?.hide();
		},
		methods: {
			getDialog() {
				if (!this.instance) {
					this.instance = this.createDialog();
				}
				return this.instance;
			},
			loc(locString) {
				return this.$bitrix.Loc.getMessage(locString);
			},
			createDialog() {
				const confirm = new ui_buttons.Button({
					text: this.loc('BIZPROCDESIGNER_EDITOR_FRAME_BLOCK_CONFIRM_SAVE'),
					useAirDesign: true,
					style: ui_buttons.AirButtonStyle.FILLED
				});
				const cancel = new ui_buttons.Button({
					text: this.loc('BIZPROCDESIGNER_EDITOR_FRAME_BLOCK_CONFIRM_ABORT'),
					useAirDesign: true,
					style: ui_buttons.AirButtonStyle.OUTLINE
				});
				const options = {
					title: this.loc('BIZPROCDESIGNER_EDITOR_FRAME_BLOCK_CONFIRM_TITLE'),
					subtitle: this.loc('BIZPROCDESIGNER_EDITOR_FRAME_BLOCK_CONFIRM_DESCRIPTION'),
					centerButtons: [cancel, confirm],
					events: {
						onHide: this.closePopup
					},
					width: 395
				};
				const dialog = new ui_system_dialog.Dialog(options);
				cancel.bindEvent('click', () => {
					this.$emit('abort');
					dialog.hide();
				});
				confirm.bindEvent('click', () => {
					this.$emit('save');
					dialog.hide();
				});
				return dialog;
			},
			closePopup() {
				this.$emit('close');
			}
		},
		template: `
		<div ref="content">
		</div>
	`
	};

