	function isFrame(block) {
		return block?.type === BLOCK_TYPES$1.FRAME;
	}

	// Property diff is not computed here: changedBlockIds is reported by the graph store from the very
	// pass that applies the properties, the only pass that still sees the previous values.
	function collectAgentTouchedBlockIds({
		changedBlockIds,
		animatedItems,
		newBlocks
	}) {
		const newBlockById = new Map(newBlocks.map(block => [block.id, block]));
		const touchedBlockIds = new Set();
		for (const item of animatedItems) {
			if (item.type === ui_blockDiagram.ANIMATED_TYPES.BLOCK && !isFrame(item.item)) {
				touchedBlockIds.add(item.item.id);
			}
		}
		for (const blockId of changedBlockIds) {
			if (!isFrame(newBlockById.get(blockId))) {
				touchedBlockIds.add(blockId);
			}
		}
		return touchedBlockIds;
	}

	/**
	 * The only touch point between the highlight feature and the graph-apply callback:
	 * turns one applied agent graph into the set of nodes to highlight.
	 *
	 * changedBlockIds comes from updateExistedBlockProperties(): the applying reports the blocks it
	 * found different, because it mutates the stored blocks in place and leaves nothing to compare.
	 */
	function highlightAgentChanges(input) {
		const store = useAgentHighlightStore();
		const touchedBlockIds = collectAgentTouchedBlockIds(input);
		if (touchedBlockIds.size > 0) {
			store.markTouched(touchedBlockIds);
		}

		// Runs on every apply and after markTouched(), so that a node this very apply highlighted is
		// cleaned up as well. The applied graph is always the whole node set, so a highlighted id
		// missing from it belongs to a node the agent has removed.
		store.retainBlocks(input.newBlocks.map(block => block.id));
	}

	/**
	 * Initialization at editor startup: feeds the store with the visible set of the
	 * diagram engine and with the tab activity, and clears the highlight when the
	 * template changes or the editor unmounts.
	 *
	 * Must be called synchronously in the app setup(): outside an effect scope neither the watchers
	 * below nor the visibilitychange listener can be stopped, and they would outlive the editor.
	 */
	function initAgentHighlight() {
		const store = useAgentHighlightStore();
		const {
			blockIntersections
		} = ui_blockDiagram.useBlockDiagram();
		const syncVisibleBlockIds = () => {
			store.setVisibleBlockIds(ui_vue3.toValue(blockIntersections.visibleBlockIds));
		};

		// The handler closes over the store captured here: declared outside setup() it would resolve the
		// store on every call, through whichever pinia happens to be the active one by then.
		const handleVisibilityChange = () => {
			store.setTabActive(!document.hidden);
		};
		store.setTabActive(!document.hidden);
		main_core.Event.bind(document, 'visibilitychange', handleVisibilityChange);
		let stopVisibleBlockIdsWatch = null;

		// visibleBlockIds is a computed set of every visible id, and this is its only standing reader:
		// kept alive, it would rebuild and compare that set on every camera frame even with nothing
		// highlighted. So the subscription lives exactly as long as the highlight does.
		ui_vue3.watch(() => store.highlightedBlockIds.size, highlightedCount => {
			if (highlightedCount > 0 && stopVisibleBlockIdsWatch === null) {
				// Read at once: while unsubscribed the store has missed every camera move.
				syncVisibleBlockIds();
				stopVisibleBlockIdsWatch = ui_vue3.watch(blockIntersections.visibleBlockIds, syncVisibleBlockIds);
			} else if (highlightedCount === 0 && stopVisibleBlockIdsWatch !== null) {
				stopVisibleBlockIdsWatch();
				stopVisibleBlockIdsWatch = null;
			}
		},
		// Synchronous on purpose: markTouched() itself brings the highlight set to life, and the
		// subscription has to be in place before that call returns, so that the first visible set
		// of the applied graph revision reaches the store and starts the countdowns.
		{
			flush: 'sync'
		});

		// A node can leave the graph outside an agent apply - deleted by hand, undone from history - and
		// retainBlocks() runs on an apply only. One still waiting for its first visibility signal has no
		// countdown to end it either, so its record would keep the highlight set non-empty, and with it the
		// subscription above, until the template changes. The count of blocks is the trigger; a change that
		// keeps it - a node deleted and another added in the same tick - is left to the next apply.
		ui_vue3.watch(() => diagramStore().blocks.length, () => {
			if (store.highlightedBlockIds.size === 0) {
				return;
			}
			store.retainBlocks(diagramStore().blocks.map(block => block.id));
		});
		ui_vue3.watch(() => diagramStore().templateId, () => {
			store.reset();
		});
		if (ui_vue3.getCurrentScope()) {
			ui_vue3.onScopeDispose(() => {
				main_core.Event.unbind(document, 'visibilitychange', handleVisibilityChange);
				// Stopped by hand: the watcher above is already stopped by the scope by now, so the
				// reset() below no longer takes the subscription off on its own.
				stopVisibleBlockIdsWatch?.();
				stopVisibleBlockIdsWatch = null;
				store.reset();
			});
		} else {
			// A broken contract, not a supported path: nothing here can be stopped without a scope.
			console.error('initAgentHighlight() must be called synchronously in setup(): with no effect scope ' + 'the visibilitychange listener and the watchers live until the page is reloaded');
		}
	}

	const dataViewApi = new bizproc_dataview.DataViewApiClient();

	function buildNodeKey(templateId, activityName) {
		return `${templateId}:${activityName}`;
	}
	function notifyError(error) {
		ui_notification.UI.Notification.Center.notify({
			content: main_core.Text.encode(error?.message ?? ''),
			autoHideDelay: 4000
		});
	}
	const useNodeDataViewsStore = ui_vue3_pinia.defineStore('bizprocdesigner-editor-node-data-views', {
		state: () => ({
			items: [],
			isLoading: false,
			loadedKey: null,
			lastFetchId: 0
		}),
		getters: {
			hasItems: state => state.items.length > 0
		},
		actions: {
			async load(templateId, activityName) {
				if (!isTemplateId(templateId) || !main_core.Type.isStringFilled(activityName)) {
					return;
				}
				if (this.loadedKey === buildNodeKey(templateId, activityName)) {
					return;
				}
				const fetchId = ++this.lastFetchId;
				this.isLoading = true;
				try {
					const data = await dataViewApi.list(templateId, activityName);
					if (this.lastFetchId !== fetchId) {
						return;
					}
					this.items = main_core.Type.isArray(data?.items) ? data.items : [];
					this.loadedKey = buildNodeKey(templateId, activityName);
				} catch (error) {
					if (this.lastFetchId !== fetchId) {
						return;
					}
					this.items = [];
					this.loadedKey = null;
					notifyError(error);
				} finally {
					if (this.lastFetchId === fetchId) {
						this.isLoading = false;
					}
				}
			},
			async remove(storageTypeId) {
				try {
					await dataViewApi.remove(storageTypeId);
					this.items = this.items.filter(item => item.storageTypeId !== storageTypeId);
					return true;
				} catch (error) {
					notifyError(error);
					return false;
				}
			},
			/**
			 * Adds or updates a view of the current node. Passing the node key marks the list as loaded for
			 * that node, so a view saved after the initial list load failed (loadedKey still null) becomes
			 * visible at once instead of hiding behind the load gate until the node is reopened.
			 */
			upsert(item, nodeKey) {
				if (!item || !main_core.Type.isNumber(item.storageTypeId)) {
					return;
				}
				if (main_core.Type.isStringFilled(nodeKey)) {
					this.loadedKey = nodeKey;
				}
				const index = this.items.findIndex(current => current.storageTypeId === item.storageTypeId);
				if (index === -1) {
					this.items.push(item);
					return;
				}
				this.items.splice(index, 1, {
					...this.items[index],
					...item
				});
			},
			reset() {
				this.items = [];
				this.isLoading = false;
				this.loadedKey = null;
				this.lastFetchId = 0;
			}
		}
	});

	const DATA_VIEWS_EVENTS = Object.freeze({
		OPEN_TABLE_SETTINGS: 'BizprocDesigner.DataViews.OpenTableSettings'
	});

	let isInstalled = false;
	let instanceSeq = 0;

	/**
	 * Bridges the node settings "data views" section to the data view editor: on the section's
	 * {@code OpenTableSettings} event it opens the editor via the definition store, forwarding the node
	 * owner context and the section's {@code onSaved} callback (which upserts the returned item). The
	 * source catalog cached by the previous session is dropped with it — a new session re-reads what the
	 * user may pick now. The stores are resolved here (setup context) and captured for the event handler.
	 *
	 * Installed once for the editor lifetime; repeated calls are ignored.
	 */
	function initDataViewEditorConnector() {
		if (isInstalled) {
			return;
		}
		isInstalled = true;
		const definitionStore = useDataViewDefinitionStore();
		const metaStore = useDataViewMetaStore();
		main_core_events.EventEmitter.subscribe(DATA_VIEWS_EVENTS.OPEN_TABLE_SETTINGS, event => {
			const data = event.getData() ?? {};
			instanceSeq += 1;
			metaStore.reset();
			definitionStore.open({
				templateId: isTemplateId(data.templateId) ? Number(data.templateId) : null,
				activityName: main_core.Type.isStringFilled(data.activityName) ? data.activityName : '',
				storageTypeId: main_core.Type.isNumber(data.storageTypeId) ? data.storageTypeId : null,
				instanceKey: String(instanceSeq),
				onSaved: main_core.Type.isFunction(data.onSaved) ? data.onSaved : null
			});
		});
	}

